import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`why-no-traffic`,heroTitle:`Find out why Google ignores you`,heroSubtitle:`Perplexity Computer checks indexing, scans for technical blockers, and turns your traffic problem into a ranked fix list.`,inputUrlCta:`Diagnose my traffic`,inputUrlPlaceholder:`yourwebsite.com`,inputUrlPrefill:`Go to {url} and diagnose why this site is not getting meaningful organic traffic. (1) Check index coverage, robots rules, canonicals, sitemap health, metadata quality, and technical blockers. (2) Review the top 20 pages for search intent alignment, content depth, internal linking, and obvious quality gaps. (3) Compare the site against stronger competitors on the same topics and identify what they cover that this site does not. (4) Call out the highest-impact fixes across technical SEO, content quality, page structure, and site architecture. (5) Deliver a single-page diagnosis with the five most important fixes ranked by effort, impact, and expected traffic gain.`,heroOverlaySteps:[`Checking index coverage, robots rules, canonicals, and sitemap health`,`Reviewing key pages for thin content, weak intent match, and internal link gaps`,`Comparing your pages against stronger competitors on the same topics`,`Single-page diagnosis with the five fixes most likely to unlock traffic`],generatingSteps:[`Visiting {url} to evaluate index status, technical setup, and page inventory`,`Designing an agent to review content quality, intent alignment, and architecture gaps`,`Configuring competitor comparisons to explain where stronger pages pull ahead`,`Packaging the findings into a ranked diagnosis with effort and impact estimates`],featureSectionTitle:`From traffic confusion to a prioritized diagnosis`,featureCardTitles:[`Connects to your SEO workflow`,`Outputs your team can fix from`],featureCardDescriptions:[`Computer breaks the diagnosis into technical checks, page reviews, competitor comparisons, and prioritization so the answer is specific to your site.`,`Search Console exports, analytics snapshots, Docs, Sheets, and planning tools can all stay connected so the fix list turns into execution.`,`Technical findings. Page-level gaps. Competitor context. Ranked next steps. Computer gives your team a diagnosis tied to what is actually suppressing visibility.`],capabilitySectionTitle:`Your SEO diagnostician, on demand`,capabilitySectionSubtitle:`Paste your site, step away, and come back to the reasons traffic is stuck.`,capabilityCards:[{title:`Indexing Checks`,description:`Computer can review robots rules, canonicals, sitemap signals, and index coverage issues that keep important pages out of search.`},{title:`Page Quality Analysis`,description:`Computer can evaluate your key pages for intent match, structure, depth, and internal linking to show why they fail to compete.`},{title:`Competitor Comparisons`,description:`Computer can compare your coverage against stronger pages and point to the missing sections, proof, or format choices costing rankings.`},{title:`Connect Your Tools`,description:`Computer can package the diagnosis into Docs, Sheets, and planning tools so owners can work through fixes without losing context.`},{title:`Fix Prioritization`,description:`Computer can rank technical and content work by expected impact so the next sprint focuses on what will move traffic first.`},{title:`Recheck Progress`,description:`Computer can revisit the site after changes, compare the new state to the old diagnosis, and identify the next constraint to remove.`}]});export{t as default};
